CREATE TABLE IF NOT EXISTS points (app TEXT NOT NULL, metric TEXT NOT NULL, ts INTEGER NOT NULL, value REAL NOT NULL, PRIMARY KEY (app, metric, ts));
CREATE INDEX IF NOT EXISTS points_ts ON points (ts);
CREATE TABLE IF NOT EXISTS daily (app TEXT NOT NULL, metric TEXT NOT NULL, day TEXT NOT NULL, value REAL NOT NULL, PRIMARY KEY (app, metric, day));
CREATE TABLE IF NOT EXISTS alerts (id INTEGER PRIMARY KEY AUTOINCREMENT, app TEXT, metric TEXT, kind TEXT, severity TEXT, title TEXT, body TEXT, ts INTEGER, acked INTEGER DEFAULT 0, dedupe TEXT UNIQUE);
CREATE INDEX IF NOT EXISTS alerts_ts ON alerts (ts);
CREATE TABLE IF NOT EXISTS health (target TEXT PRIMARY KEY, app TEXT, url TEXT, ok INTEGER, code INTEGER, ms INTEGER, ts INTEGER, since INTEGER, fails INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS reviews (id TEXT PRIMARY KEY, app TEXT, store TEXT, rating INTEGER, title TEXT, body TEXT, ts INTEGER, territory TEXT);
CREATE TABLE IF NOT EXISTS kv (k TEXT PRIMARY KEY, v TEXT, ts INTEGER);
CREATE TABLE IF NOT EXISTS insights (id INTEGER PRIMARY KEY AUTOINCREMENT, app TEXT, ts INTEGER, kind TEXT, text TEXT);
CREATE TABLE IF NOT EXISTS rc_events (id TEXT PRIMARY KEY, app TEXT, type TEXT, period_type TEXT, product TEXT, price_usd REAL, store TEXT, country TEXT, ts INTEGER, trial_conversion INTEGER, env TEXT, takehome REAL, tax REAL);
CREATE INDEX IF NOT EXISTS rc_events_ts ON rc_events (ts);
CREATE TABLE IF NOT EXISTS acq (app TEXT NOT NULL, channel TEXT NOT NULL, day TEXT NOT NULL, src TEXT NOT NULL, n REAL NOT NULL, PRIMARY KEY (app, channel, day, src));
CREATE TABLE IF NOT EXISTS acq_land (app TEXT NOT NULL, day TEXT NOT NULL, src TEXT NOT NULL, page TEXT NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (app, day, src, page));
CREATE TABLE IF NOT EXISTS acq_ref (app TEXT NOT NULL, host TEXT NOT NULL, src TEXT, n INTEGER NOT NULL, last INTEGER, PRIMARY KEY (app, host));
CREATE TABLE IF NOT EXISTS intraday (app TEXT NOT NULL, metric TEXT NOT NULL, ts INTEGER NOT NULL, value REAL NOT NULL, PRIMARY KEY (app, metric, ts));
CREATE INDEX IF NOT EXISTS intraday_ts ON intraday (ts);
CREATE INDEX IF NOT EXISTS intraday_metric_ts ON intraday (metric, ts);
CREATE TABLE IF NOT EXISTS meta_daily (app TEXT NOT NULL, day TEXT NOT NULL, spend REAL NOT NULL, impressions INTEGER NOT NULL, clicks INTEGER NOT NULL, installs INTEGER NOT NULL, trials INTEGER NOT NULL, subs INTEGER NOT NULL, purchases INTEGER NOT NULL, ts INTEGER NOT NULL, PRIMARY KEY (app, day));
